window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"vV3GjZxQZCQ","speaker":"Taye Atskeselassie Amde","role":"President","country":"Ethiopia","region":"Africa","url":"https://www.youtube.com/watch?v=vV3GjZxQZCQ","date":"20260923","title":"🇪🇹 Ethiopia - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":744,"words":1416,"counts":{"claims":19,"promises":2,"attacks":1},"topics":[{"topic":"UN governance","share":0.1164,"seconds":87},{"topic":"Ethiopia agriculture","share":0.0988,"seconds":74},{"topic":"Africa technology","share":0.0953,"seconds":71},{"topic":"Sudan conflict","share":0.0914,"seconds":68},{"topic":"UN diplomacy","share":0.09,"seconds":67},{"topic":"Ethiopia environment","share":0.0885,"seconds":66},{"topic":"International security","share":0.0879,"seconds":65},{"topic":"Ethiopia development","share":0.0844,"seconds":63},{"topic":"Ethiopia climate policy","share":0.0836,"seconds":62},{"topic":"Ethiopia trade","share":0.0819,"seconds":61},{"topic":"Global economy","share":0.0818,"seconds":61}],"timeline":[[11,73,null],[74,141,"UN diplomacy"],[142,208,"International security"],[209,270,"Global economy"],[271,333,"Ethiopia climate policy"],[334,405,"Africa technology"],[407,493,"UN governance"],[494,563,"Sudan conflict"],[564,637,"Ethiopia agriculture"],[639,705,"Ethiopia environment"],[706,769,"Ethiopia development"],[770,831,"Ethiopia trade"],[831,864,null]],"stances":{"UN diplomacy":"Taye Atskeselassie Amde expresses appreciation for the new and previous UNGA presidents and emphasizes that lasting peace requires cooperation rather than domination.","International security":"Taye Atskeselassie Amde argues that nations must actively reinforce collective security ideals to prevent global conflict, citing Ethiopia's historical refusal to surrender to fascist aggression as a model of foundational courage.","Global economy":"Taye Atskeselassie Amde states that while the UN has made progress against poverty, current efforts are insufficient due to wealth concentration and a lack of moral courage to fulfill past promises.","Ethiopia climate policy":"Taye Atskeselassie Amde states that Ethiopia will host COP 32 in November 2027 to provide a platform for climate action and invites world leaders to attend.","Africa technology":"Taye Atskeselassie Amde argues that Africa must lead the AI revolution to avoid global inequality and cites Ethiopian initiatives as evidence of readiness.","UN governance":"Taye Atskeselassie Amde demands immediate justice and comprehensive reform of the UN Security Council to ensure equality for Africa.","Sudan conflict":"Taye Atskeselassie Amde states that Ethiopia supports a Sudan-led and Sudan-owned peace process for the region.","Ethiopia agriculture":"Taye Atskeselassie Amde states that Ethiopia has achieved significant progress in food security by transitioning from a wheat importer to a major producer through climate-resilient agriculture and national dialogue.","Ethiopia environment":"Taye Atskeselassie Amde states that the green legacy initiative has successfully planted 56 billion trees and is expected to sequester significant carbon dioxide annually, while highlighting Ethiopia's clean energy targets and the Grand Ethiopian Renaissance Dam as a pan-African project for regional prosperity.","Ethiopia development":"Taye Atskeselassie Amde states that Ethiopia is investing in a major international airport to support continental trade and emphasizes the necessity of sea access for sustained economic development.","Ethiopia trade":"Taye Atskeselassie Amde states that Ethiopia is pursuing diplomatic avenues to secure sea access for integration into the global trading system and emphasizes the need for collective collaboration to revive multilateralism."},"claims":[{"t":103,"quote":"63 years ago in 1963, Emperor Hila Salassi famously cautioned this global community by stating, \"Lasting peace can be achieved only when nations recognize that their true strengths lies not in the domination of others but in cooperation anchored upon a genuine","topic":"UN diplomacy","kind":"fact"},{"t":130,"quote":"As a founding member of the United Nations, Ethiopia bears both the scars of historical betrayal and the unyielding conviction of a survivor.","topic":"UN diplomacy","kind":"fact"},{"t":142,"quote":"When the League of Nations abandoned our appeal against fascist aggression in the we didn't surrender to despair and dissolution.","topic":"International security","kind":"fact"},{"t":154,"quote":"We resortly stood firm as champions of collective security helping the birds of the very organization in which we stand for.","topic":"International security","kind":"self_credit"},{"t":234,"quote":"The United Nation has achieved remarkable victories against extreme poverty, but it has never been enough.","topic":"Global economy","kind":"fact"},{"t":243,"quote":"While wealth accumulates in the hands of the few, billions endure the downside of structural deprivation.","topic":"Global economy","kind":"fact"},{"t":303,"quote":"my country Ethiopia will proudly host COP 32 in November 2027","topic":"Ethiopia climate policy","kind":"fact"},{"t":379,"quote":"A case in point is Ethus initiative of 5 million quarters program and the soontobe commissioned university of artificial intelligence reaffirms that our continent is ready to build the future.","topic":"Africa technology","kind":"fact"},{"t":432,"quote":"How can a world with the right conscience justify the denial of 1.6 billion Africans the right to equal","topic":"UN governance","kind":"number"},{"t":453,"quote":"Ethiopia has diligently worked to promote cooperation and regional integration through infrastructure development, trade, and people-to-people relationship in the Horn of Africa.","topic":"UN governance","kind":"fact"},{"t":554,"quote":"We recently held a democratic election that laid a strong foundation for a free, fair and transparent political dispensation.","topic":"Sudan conflict","kind":"fact"},{"t":608,"quote":"we were able to produce an improved climate resilient wheat variety seed","topic":"Ethiopia agriculture","kind":"fact"},{"t":614,"quote":"In a very short period, we have transitioned from a wheat importer to one of the largest wheat producer in Africa","topic":"Ethiopia agriculture","kind":"number"},{"t":639,"quote":"Since the launch of the green legacy initiative in 2019, we were able to plant 56 billion trees which is not only expanding our forest coverage but significantly restoring our ecosystem.","topic":"Ethiopia environment","kind":"number"},{"t":655,"quote":"At this stage, this initiative is expected to sequestering approximately 1.2 two billion metric tons of carbon dioxide annually.","topic":"Ethiopia environment","kind":"number"},{"t":669,"quote":"As one of the powerhouse of clean energy with a total potential of 60,000 megawatts, Ethiopia targets to generate 13,000 megawatt by 2030 aiming also to scale up our energy supply across East African powerpool","topic":"Ethiopia environment","kind":"number"},{"t":712,"quote":"the government is investing in an international airport was 12.5 billion US dollars which will handle 110 million passengers and about 4 million tons of cargo annually.","topic":"Ethiopia development","kind":"number"},{"t":770,"quote":"We believe that maritime access can be managed for the common benefit and progress of all countries in the region.","topic":"Ethiopia trade","kind":"fact"},{"t":783,"quote":"we are pursuing all possible diplomatic avenues to secure access to and from the sea to ensure Ethiopia's integration into a global trading system.","topic":"Ethiopia trade","kind":"fact"}],"promises":[{"t":310,"quote":"Ethiopia will help organize a vibrant and inclusive platform for the private sector and international stakeholders to pioneer tangible solution to climate action","topic":"Ethiopia climate policy","kind":"promise"},{"t":536,"quote":"Ethiopia will continue to commit to the realization of our overarching goal of building a democratic and prosperous country.","topic":"Sudan conflict","kind":"promise"}],"attacks":[{"t":471,"quote":"reckless external actors who are habitually engaged in fuming Despite continued interference in our internal affairs by adversarial elements","topic":"UN governance","target":"External adversaries"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":11,"topic":null,"text":"The assembly will hear uh the address of his excellency T alasia amde president of the Federal Democratic Republic of Ethiopia. I request protocol to escort his excellency and invite him to address the assembly. Kaluru Rahman, President of the 81st session of the United General Assembly. Excellency Antonio Guterres, Secretary General of the United Nations. ladies and gentlemen, on behalf of Ethiopia, I wish to congratulate you, Mr."},{"t":74,"topic":"UN diplomacy","text":"President, on your election as president of the 81st session of the United Nations General I also wish to express my sincere appreciation to your predecessor, her excellency Miss Analina Barbuk, for her leadership during our atheist session. Mr. President, we assembled at a historic moment for 63 years ago in 1963, Emperor Hila Salassi famously cautioned this global community by stating, \"Lasting peace can be achieved only when nations recognize that their true strengths lies not in the domination of others but in cooperation anchored upon a genuine As a founding member of the United Nations, Ethiopia bears both the scars of historical betrayal and the unyielding conviction of a survivor."},{"t":142,"topic":"International security","text":"When the League of Nations abandoned our appeal against fascist aggression in the we didn't surrender to despair and dissolution. We resortly stood firm as champions of collective security helping the birds of the very organization in which we stand for. Today we call upon the community of nations to summon that same foundational courage to actively reinforce the very ideals that help prevent global conflict and the scourge of war. The question therefore is how much longer shall we wait before the pillars of collective security fractured beyond repair. This is exactly what drives the significance of multilateralism not as a diplomat convenience but as a living shield rooted in sovereign equality to address the shifting tides of power politics."},{"t":209,"topic":"Global economy","text":"Mr. President, I would like to thank the Secretary General for placing before us the defining imperatives of our era, namely artificial intelligence, the climate crisis, and deepening global These are not only policy choices, they are the pivots upon which human destiny is determined. The United Nation has achieved remarkable victories against extreme poverty, but it has never been enough. While wealth accumulates in the hands of the few, billions endure the downside of structural deprivation. However, we believe that we are capable of charting the blueprint, the resources, and the wisdom to bridge this divide. What the global community lack is not the means of implementation but the moral courage to keep the promise we made eight decades ago."},{"t":271,"topic":"Ethiopia climate policy","text":"Poverty and systemic inequality al also fuel ecological and environmental crisis. Excessive consumption of the few drives the emission that is currently choking our planet. Yet delayed promise add a brutal toll in the loss of lives and the devastation of infrastructures. If we are to survive this crisis, we must act now and act fast. Speaking of actions, my country Ethiopia will proudly host COP 32 in November 2027. Ethiopia will help organize a vibrant and inclusive platform for the private sector and international stakeholders to pioneer tangible solution to climate action. In this connection, I sincerely invite all world leaders to come to Ethiopia and leave their footprints at this important global climate summit."},{"t":334,"topic":"Africa technology","text":"With regard to the digital revolution and artificial intelligence, Africa is compelled to ask a very defining question. Will the age of the AI become another instrument of global inequality or will it be a catalyst for our collective growth? We must ensure that the global south leads this technological revolution rather than remain a helpless spectator. Nevertheless, some of the initiatives we see from the global south give a beacon of hope that we indeed can attain technological advancement through foresight and leadership. A case in point is Ethus initiative of 5 million quarters program and the soontobe commissioned university of artificial intelligence reaffirms that our continent is ready to build the future. Mr. President, Ethiopia remains steadfast in its belief that the United Nation must be fundamentally reformed to best address the shifting global challenge."},{"t":407,"topic":"UN governance","text":"The UN reform must reflect our highest aspiration to witness an organization anchored in true equality and justice. Africa has waited for too long in the shadow of global decision making. Now it is demanding immediate justice through the comprehensive reform of the United Nation Security Council with genuine political goodwill. How can a world with the right conscience justify the denial of 1.6 billion Africans the right to equal That indeed is a generational quest for truth and for morality. Mr. President, Ethiopia has diligently worked to promote cooperation and regional integration through infrastructure development, trade, and people-to-people relationship in the Horn of Africa. We have achieved notable progress with several of our neighbors in spite of attempts by reckless external actors who are habitually engaged in fuming Despite continued interference in our internal affairs by adversarial elements, we have exercised immense restraint and remained by the firm conviction of becoming one of the most prosperous and dynamic development engines in the Africa."},{"t":494,"topic":"Sudan conflict","text":"Our message to forces of destruction and mayhem is loud and clear. We urge them to respect the sacred right of the people of the Horn of Africa to live in peace and Turning to the wider region, Ethiopia has consistently supported efforts by subregional and regional organization to bring durable and lasting peace in the Sudan. We firmly believe that a peaceful resolution can only be achieved through a Sudanistled and Sudanis owned peace process that reflects the true will and aspiration of the Sudan people. Mr. President, Ethiopia will continue to commit to the realization of our overarching goal of building a democratic and prosperous country. The progress we have achieved so far on various facets of government reflects this firm and strong resol. We recently held a democratic election that laid a strong foundation for a free, fair and transparent political dispensation."},{"t":564,"topic":"Ethiopia agriculture","text":"Equally, in our relentless pursuit of building national consensus, the National Dialoga Commission has convened the first historical summit where citizens from every corner of the country and from all walks of life deliberate on critical issues of national importance. It has now opened a glorious new chapter in our political history that help strengthen our democratic institutions. A significant leap has also been achieved in attaining food security. As part of fulfilling our commitment to enhance resilience to climate shock, we were able to produce an improved climate resilient wheat variety seed. In a very short period, we have transitioned from a wheat importer to one of the largest wheat producer in Africa. At a time where food provision has become a political battleground and the global food supply hangs precariously in the balance, we send a clear message that Africa can feed itself."},{"t":639,"topic":"Ethiopia environment","text":"Since the launch of the green legacy initiative in 2019, we were able to plant 56 billion trees which is not only expanding our forest coverage but significantly restoring our ecosystem. At this stage, this initiative is expected to sequestering approximately 1.2 two billion metric tons of carbon dioxide annually. As one of the powerhouse of clean energy with a total potential of 60,000 megawatts, Ethiopia targets to generate 13,000 megawatt by 2030 aiming also to scale up our energy supply across East African powerpool and In this regard, the Grand Tip and Renaissance Dam stands as a monumental pan-African clean energy project providing that our shared waters and resources can generate progress and development for collective regional prosperity."},{"t":706,"topic":"Ethiopia development","text":"Moreover, adding to growing portfolio mega projects executions, the government is investing in an international airport was 12.5 billion US dollars which will handle 110 million passengers and about 4 million tons of cargo annually. This project will play a Catholic role in the African continental free trade area. to sustain and scale up the success we have achieved in renewable energy, connectivity, food security, manufacturing and urban development, Ethiopia calls for a genuine and sustained regional and international Despite this tremendous achievement, Mr. President, we have come to recognize that our efforts to build a strong economy cannot generate a sustained development without reliable and dependable access to the sea."},{"t":770,"topic":"Ethiopia trade","text":"We believe that maritime access can be managed for the common benefit and progress of all countries in the region. It is up to it is upon this unwavering question aspiration that we are pursuing all possible diplomatic avenues to secure access to and from the sea to ensure Ethiopia's integration into a global trading system. Mr. President, as we attend this August assembly, we are reminded not only by the ideals and values of our organization, but of the imperatives we must uphold as enshrined in the charter. We stand a better chance of surviving and succeeding if we continuously and collectively shape our collaboration. This will certainly revive multilateralism to meet the demands of the current and f future generations. In conclusion, Mr."},{"t":831,"topic":null,"text":"President, I give you my reassurance that Ethiopia remains steadfast as it has always been in its historic commitment in upholding human dignity, justice, and the unyielding solidarity of all free peoples. I thank you, Mr. President. On behalf of the assembly, I wish to thank the president of the Federal Democratic Republic of Ethiopia. Uh we have heard the last speaker in the general debate for this meeting,"}],"compare":[{"topic":"UN & its reform","share":0.2064,"mean":0.2047,"rank":88,"others":170},{"topic":"Africa","share":0.0953,"mean":0.0231,"rank":20,"others":36},{"topic":"Sudan","share":0.0914,"mean":0.0068,"rank":4,"others":15},{"topic":"International Law & Order","share":0.0879,"mean":0.0603,"rank":52,"others":102},{"topic":"Global Economy","share":0.0818,"mean":0.0142,"rank":12,"others":31}]};
